    29→// EntireSettings represents the .entire/settings.json configuration
    30→type EntireSettings struct {
    31→	// Strategy is the name of the git strategy to use
    32→	Strategy string `json:"strategy"`
    33→
    34→	// Enabled indicates whether Entire is active. When false, CLI commands
    35→	// show a disabled message and hooks exit silently. Defaults to true.
    36→	Enabled bool `json:"enabled"`
    37→
    38→	// LocalDev indicates whether to use "go run" instead of the "entire" binary
    39→	// This is used for development when the binary is not installed
    40→	LocalDev bool `json:"local_dev,omitempty"`
    41→
    42→	// LogLevel sets the logging verbosity (debug, info, warn, error).
    43→	// Can be overridden by ENTIRE_LOG_LEVEL environment variable.
    44→	// Defaults to "info".
    45→	LogLevel string `json:"log_level,omitempty"`
    46→
    47→	// StrategyOptions contains strategy-specific configuration
    48→	StrategyOptions map[string]interface{} `json:"strategy_options,omitempty"`
    49→
