    55→// LoadEntireSettings loads the Entire settings from .entire/settings.json,
    56→// then applies any overrides from .entire/settings.local.json if it exists.
    57→// Returns default settings if neither file exists.
    58→// Works correctly from any subdirectory within the repository.
    59→func LoadEntireSettings() (*EntireSettings, error) {
    60→	// Get absolute paths for settings files
    61→	settingsFileAbs, err := paths.AbsPath(EntireSettingsFile)
    62→	if err != nil {
    63→		settingsFileAbs = EntireSettingsFile // Fallback to relative
    64→	}
    65→	localSettingsFileAbs, err := paths.AbsPath(EntireSettingsLocalFile)
    66→	if err != nil {
    67→		localSettingsFileAbs = EntireSettingsLocalFile // Fallback to relative
    68→	}
    69→
    70→	// Load base settings
    71→	settings, err := loadSettingsFromFile(settingsFileAbs)
    72→	if err != nil {
    73→		return nil, fmt.Errorf("reading settings file: %w", err)
    74→	}
    75→
    76→	// Apply local overrides if they exist
    77→	localData, err := os.ReadFile(localSettingsFileAbs) //nolint:gosec // path is from AbsPath or constant
    78→	if err != nil {
    79→		if !os.IsNotExist(err) {
    80→			return nil, fmt.Errorf("reading local settings file: %w", err)
    81→		}
    82→		// Local file doesn't exist, continue without overrides
    83→	} else {
    84→		if err := mergeSettingsJSON(settings, localData); err != nil {
    85→			return nil, fmt.Errorf("merging local settings: %w", err)
    86→		}
    87→	}
    88→
    89→	applyDefaultStrategy(settings)
    90→
    91→	return settings, nil
    92→}
    93→
    94→// mergeSettingsJSON merges JSON data into existing settings.
    95→// Only non-zero values from the JSON override existing settings.
    96→func mergeSettingsJSON(settings *EntireSettings, data []byte) error {
    97→	// Parse into a map to check which fields are present
    98→	var raw map[string]json.RawMessage
    99→	if err := json.Unmarshal(data, &raw); err != nil {
   100→		return fmt.Errorf("parsing JSON: %w", err)
   101→	}
   102→
   103→	// Override strategy if present and non-empty
   104→	if strategyRaw, ok := raw["strategy"]; ok {
   105→		var s string
   106→		if err := json.Unmarshal(strategyRaw, &s); err != nil {
   107→			return fmt.Errorf("parsing strategy field: %w", err)
   108→		}
   109→		if s != "" {
   110→			settings.Strategy = s
   111→		}
   112→	}
   113→
   114→	// Override enabled if present
   115→	if enabledRaw, ok := raw["enabled"]; ok {
   116→		var e bool
   117→		if err := json.Unmarshal(enabledRaw, &e); err != nil {
   118→			return fmt.Errorf("parsing enabled field: %w", err)
   119→		}
   120→		settings.Enabled = e
   121→	}
   122→
   123→	// Override local_dev if present
   124→	if localDevRaw, ok := raw["local_dev"]; ok {
   125→		var ld bool
   126→		if err := json.Unmarshal(localDevRaw, &ld); err != nil {
   127→			return fmt.Errorf("parsing local_dev field: %w", err)
   128→		}
   129→		settings.LocalDev = ld
   130→	}
   131→
   132→	// Override log_level if present and non-empty
   133→	if logLevelRaw, ok := raw["log_level"]; ok {
   134→		var ll string
   135→		if err := json.Unmarshal(logLevelRaw, &ll); err != nil {
   136→			return fmt.Errorf("parsing log_level field: %w", err)
   137→		}
   138→		if ll != "" {
   139→			settings.LogLevel = ll
   140→		}
   141→	}
   142→
   143→	// Merge strategy_options if present
   144→	if optionsRaw, ok := raw["strategy_options"]; ok {
   145→		var opts map[string]interface{}
   146→		if err := json.Unmarshal(optionsRaw, &opts); err != nil {
   147→			return fmt.Errorf("parsing strategy_options field: %w", err)
   148→		}
   149→		if settings.StrategyOptions == nil {
   150→			settings.StrategyOptions = opts
   151→		} else {
   152→			for k, v := range opts {
   153→				settings.StrategyOptions[k] = v
   154→			}
   155→		}
   156→	}
   157→
   158→	// Override telemetry if present
   159→	if telemetryRaw, ok := raw["telemetry"]; ok {
   160→		var t bool
   161→		if err := json.Unmarshal(telemetryRaw, &t); err != nil {
   162→			return fmt.Errorf("parsing telemetry field: %w", err)
   163→		}
   164→		settings.Telemetry = &t
   165→	}
   166→
   167→	return nil
   168→}
