   180→// loadSettingsFromFile loads settings from a specific file path.
   181→// Returns default settings if the file doesn't exist.
   182→func loadSettingsFromFile(filePath string) (*EntireSettings, error) {
   183→	settings := &EntireSettings{
   184→		Strategy: strategy.DefaultStrategyName,
   185→		Enabled:  true, // Default to enabled
   186→	}
   187→
   188→	data, err := os.ReadFile(filePath) //nolint:gosec // path is from caller
   189→	if err != nil {
   190→		if os.IsNotExist(err) {
   191→			return settings, nil
   192→		}
   193→		return nil, fmt.Errorf("%w", err)
   194→	}
   195→
   196→	if err := json.Unmarshal(data, settings); err != nil {
   197→		return nil, fmt.Errorf("parsing settings file: %w", err)
   198→	}
   199→	applyDefaultStrategy(settings)
   200→
   201→	return settings, nil
   202→}
   203→
   204→func applyDefaultStrategy(settings *EntireSettings) {
   205→	// Apply defaults if not set
   206→	if settings.Strategy == "" {
   207→		settings.Strategy = strategy.DefaultStrategyName
   208→	}
   209→}
   210→
   211→func saveSettingsToFile(settings *EntireSettings, filePath string) error {
   212→	// Get absolute path for the file
   213→	filePathAbs, err := paths.AbsPath(filePath)
   214→	if err != nil {
   215→		filePathAbs = filePath // Fallback to relative
   216→	}
   217→
   218→	// Ensure directory exists
   219→	dir := filepath.Dir(filePathAbs)
   220→	if err := os.MkdirAll(dir, 0o750); err != nil {
   221→		return fmt.Errorf("creating settings directory: %w", err)
   222→	}
   223→
   224→	data, err := jsonutil.MarshalIndentWithNewline(settings, "", "  ")
   225→	if err != nil {
   226→		return fmt.Errorf("marshaling settings: %w", err)
   227→	}
   228→
   229→	//nolint:gosec // G306: settings file is config, not secrets; 0o644 is appropriate
   230→	if err := os.WriteFile(filePathAbs, data, 0o644); err != nil {
   231→		return fmt.Errorf("writing settings file: %w", err)
   232→	}
   233→	return nil
   234→}
   235→
   236→// IsEnabled returns whether Entire is currently enabled.
   237→// Returns true by default if settings cannot be loaded.
   238→func IsEnabled() (bool, error) {
   239→	settings, err := LoadEntireSettings()
   240→	if err != nil {
   241→		return true, err
   242→	}
   243→	return settings.Enabled, nil
   244→}
   245→
   246→// GetStrategy returns the configured strategy instance.
   247→// Falls back to default if the configured strategy is not found.
   248→//
   249→//nolint:ireturn // Factory pattern requires returning the interface
   250→func GetStrategy() strategy.Strategy {
   251→	settings, err := LoadEntireSettings()
   252→	if err != nil {
   253→		// Fall back to default on error
   254→		logging.Info(context.Background(), "falling back to default strategy - failed to load settings",
   255→			slog.String("error", err.Error()))
   256→		return strategy.Default()
   257→	}
   258→
   259→	s, err := strategy.Get(settings.Strategy)
   260→	if err != nil {
   261→		// Fall back to default if strategy not found
   262→		logging.Info(context.Background(), "falling back to default strategy - configured strategy not found",
   263→			slog.String("configured", settings.Strategy),
   264→			slog.String("error", err.Error()))
   265→		return strategy.Default()
   266→	}
   267→
   268→	return s
   269→}
