   271→// GetLogLevel returns the configured log level from settings.
   272→// Returns empty string if not configured (caller should use default).
   273→// Note: ENTIRE_LOG_LEVEL env var takes precedence; check it first.
   274→func GetLogLevel() string {
   275→	settings, err := LoadEntireSettings()
