   282→// IsMultiSessionWarningDisabled checks if multi-session warnings are disabled.
   283→// Returns false (show warnings) by default if settings cannot be loaded or the key is missing.
   284→func IsMultiSessionWarningDisabled() bool {
   285→	settings, err := LoadEntireSettings()
   286→	if err != nil {
   287→		return false // Default: show warnings
   288→	}
   289→	if settings.StrategyOptions == nil {
   290→		return false
   291→	}
   292→	if disabled, ok := settings.StrategyOptions["disable_multisession_warning"].(bool); ok {
   293→		return disabled
   294→	}
