   298→// GetAgentsWithHooksInstalled returns names of agents that have hooks installed.
   299→func GetAgentsWithHooksInstalled() []agent.AgentName {
   300→	var installed []agent.AgentName
   301→	for _, name := range agent.List() {
   302→		ag, err := agent.Get(name)
   303→		if err != nil {
   304→			continue
   305→		}
   306→		if hs, ok := ag.(agent.HookSupport); ok && hs.AreHooksInstalled() {
   307→			installed = append(installed, name)
   308→		}
   309→	}
   310→	return installed
   311→}
