     2→
     3→import (
     4→	"encoding/json"
     5→	"fmt"
     6→)
     7→
     8→// MaxDescriptionLength is the maximum length for descriptions in commit messages
     9→// before truncation occurs.
    10→const MaxDescriptionLength = 60
    11→
    12→// TruncateDescription truncates a string to maxLen characters, adding "..." if truncated.
    13→// If maxLen is less than 3, returns a string of dots up to maxLen.
    14→func TruncateDescription(s string, maxLen int) string {
    15→	if len(s) <= maxLen {
    16→		return s
    17→	}
    18→	if maxLen < 3 {
    19→		return s[:maxLen]
    20→	}
    21→	return s[:maxLen-3] + "..."
    22→}
    23→
    24→// FormatSubagentEndMessage formats a commit message for when a subagent completes.
    25→// Format: "Completed '<agent-type>' agent: <description> (<tool-use-id>)"
    26→//
    27→// Edge cases:
    28→//   - Empty description: "Completed '<agent-type>' agent (<tool-use-id>)"
    29→//   - Empty agentType: "Completed agent: <description> (<tool-use-id>)"
    30→//   - Both empty: "Task: <tool-use-id>"
    31→func FormatSubagentEndMessage(agentType, description, toolUseID string) string {
    32→	return formatSubagentMessage("Completed", agentType, description, toolUseID)
    33→}
    34→
    35→// formatSubagentMessage is a shared helper for start/end messages.
    36→func formatSubagentMessage(verb, agentType, description, toolUseID string) string {
    37→	// Both empty - fall back to simple format
    38→	if agentType == "" && description == "" {
    39→		return "Task: " + toolUseID
    40→	}
    41→
    42→	// Truncate description if needed
    43→	if description != "" {
    44→		description = TruncateDescription(description, MaxDescriptionLength)
    45→	}
    46→
    47→	// Build message based on what fields are present
    48→	if agentType != "" && description != "" {
    49→		return fmt.Sprintf("%s '%s' agent: %s (%s)", verb, agentType, description, toolUseID)
    50→	}
    51→	if agentType != "" {
    52→		return fmt.Sprintf("%s '%s' agent (%s)", verb, agentType, toolUseID)
    53→	}
    54→	// agentType is empty, description is present
    55→	return fmt.Sprintf("%s agent: %s (%s)", verb, description, toolUseID)
    56→}
    57→
    58→// FormatIncrementalSubject formats the commit message subject for incremental checkpoints.
    59→// Delegates to FormatIncrementalMessage.
    60→//
    61→// Note: The incrementalType, subagentType, and taskDescription parameters are kept for
    62→// API compatibility but are not currently used. They may be used in the future for
    63→// different checkpoint types.
    64→func FormatIncrementalSubject(
    65→	incrementalType string,
    66→	subagentType string,
    67→	taskDescription string,
    68→	todoContent string,
    69→	incrementalSequence int,
    70→	shortToolUseID string,
    71→) string {
    72→	// Currently all incremental checkpoints use the same format
    73→	_, _, _ = incrementalType, subagentType, taskDescription // Silence unused warnings
    74→	return FormatIncrementalMessage(todoContent, incrementalSequence, shortToolUseID)
    75→}
    76→
    77→// FormatIncrementalMessage formats a commit message for an incremental checkpoint.
    78→// Format: "<todo-content> (<tool-use-id>)"
    79→//
    80→// If todoContent is empty, falls back to: "Checkpoint #<sequence>: <tool-use-id>"
    81→func FormatIncrementalMessage(todoContent string, sequence int, toolUseID string) string {
    82→	if todoContent == "" {
    83→		return fmt.Sprintf("Checkpoint #%d: %s", sequence, toolUseID)
    84→	}
    85→
    86→	// Truncate todo content if needed
    87→	todoContent = TruncateDescription(todoContent, MaxDescriptionLength)
    88→	return fmt.Sprintf("%s (%s)", todoContent, toolUseID)
    89→}
    90→
    91→// todoItem represents a single item in the TodoWrite tool_input.todos array.
    92→type todoItem struct {
    93→	Content    string `json:"content"`
    94→	ActiveForm string `json:"activeForm"`
    95→	Status     string `json:"status"`
    96→}
    97→
    98→// ExtractLastCompletedTodo extracts the content of the last completed todo item from tool_input.
    99→// This represents the work that was just finished and is used for commit messages.
   100→//
   101→// When TodoWrite is called in PostToolUse, the NEW list is provided which has the
   102→// just-completed work marked as "completed". The last completed item is the most
   103→// recently finished task.
   104→//
   105→// Returns empty string if no completed items exist or JSON is invalid.
   106→func ExtractLastCompletedTodo(todosJSON []byte) string {
   107→	if len(todosJSON) == 0 {
   108→		return ""
   109→	}
   110→
   111→	var todos []todoItem
   112→	if err := json.Unmarshal(todosJSON, &todos); err != nil {
   113→		return ""
   114→	}
   115→
   116→	// Find the last completed item - this is the work that was just finished
   117→	var lastCompleted string
   118→	for _, todo := range todos {
   119→		if todo.Status == "completed" {
   120→			lastCompleted = todo.Content
   121→		}
   122→	}
   123→	return lastCompleted
   124→}
   125→
   126→// CountTodos returns the number of todo items in the JSON array.
   127→// Returns 0 if the JSON is invalid or empty.
   128→func CountTodos(todosJSON []byte) int {
   129→	if len(todosJSON) == 0 {
   130→		return 0
   131→	}
   132→
   133→	var todos []todoItem
   134→	if err := json.Unmarshal(todosJSON, &todos); err != nil {
   135→		return 0
   136→	}
   137→
   138→	return len(todos)
   139→}
   140→
   141→// ExtractInProgressTodo extracts the content of the in-progress todo item from tool_input.
   142→// This is used for commit messages in incremental checkpoints.
   143→//
   144→// Priority order:
   145→//  1. in_progress item (current work)
   146→//  2. first pending item (next work - fallback)
   147→//  3. last completed item (final work just finished)
   148→//  4. first item with unknown status (edge case)
   149→//  5. empty string (no items)
   150→//
   151→// Returns empty string if no suitable item is found or JSON is invalid.
   152→func ExtractInProgressTodo(todosJSON []byte) string {
   153→	if len(todosJSON) == 0 {
   154→		return ""
   155→	}
   156→
   157→	var todos []todoItem
   158→	if err := json.Unmarshal(todosJSON, &todos); err != nil {
   159→		return ""
   160→	}
   161→
   162→	if len(todos) == 0 {
   163→		return ""
   164→	}
   165→
   166→	// Look for in_progress item first (case-sensitive match)
   167→	for _, todo := range todos {
   168→		if todo.Status == "in_progress" {
   169→			return todo.Content
   170→		}
   171→	}
   172→
   173→	// Fall back to first pending item
   174→	for _, todo := range todos {
   175→		if todo.Status == "pending" {
   176→			return todo.Content
   177→		}
   178→	}
   179→
   180→	// Fall back to last completed item (represents the work that was just finished)
   181→	var lastCompleted string
   182→	for _, todo := range todos {
   183→		if todo.Status == "completed" {
   184→			lastCompleted = todo.Content
   185→		}
   186→	}
   187→	if lastCompleted != "" {
   188→		return lastCompleted
   189→	}
   190→
   191→	// If no in_progress, pending, or completed items, but there are items with
   192→	// unrecognized status, return first item's content as a fallback (handles edge cases).
   193→	if todos[0].Content != "" {
   194→		return todos[0].Content
   195→	}
   196→
   197→	return ""
   198→}
