    99→// CondenseSession condenses a session's shadow branch to permanent storage.
   100→// checkpointID is the 12-hex-char value from the Entire-Checkpoint trailer.
   101→// Metadata is stored at sharded path: <checkpoint_id[:2]>/<checkpoint_id[2:]>/
   102→// Uses checkpoint.GitStore.WriteCommitted for the git operations.
   103→func (s *ManualCommitStrategy) CondenseSession(repo *git.Repository, checkpointID id.CheckpointID, state *SessionState) (*CondenseResult, error) {
   104→	// Get shadow branch
   105→	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit)
   106→	refName := plumbing.NewBranchReferenceName(shadowBranchName)
   107→	ref, err := repo.Reference(refName, true)
   108→	if err != nil {
   109→		return nil, fmt.Errorf("shadow branch not found: %w", err)
   110→	}
   111→
   112→	// Extract session data from the shadow branch
   113→	// Use tracked files from session state instead of collecting all files from tree
   114→	// Pass agent type to handle different transcript formats (JSONL for Claude, JSON for Gemini)
   115→	sessionData, err := s.extractSessionData(repo, ref.Hash(), state.SessionID, state.FilesTouched, state.AgentType)
   116→	if err != nil {
   117→		return nil, fmt.Errorf("failed to extract session data: %w", err)
   118→	}
   119→
   120→	// Get checkpoint store
   121→	store, err := s.getCheckpointStore()
   122→	if err != nil {
   123→		return nil, fmt.Errorf("failed to get checkpoint store: %w", err)
   124→	}
   125→
   126→	// Get author info
   127→	authorName, authorEmail := GetGitAuthorFromRepo(repo)
   128→
   129→	// Get current branch name
   130→	branchName := GetCurrentBranchName(repo)
   131→
   132→	// Calculate initial attribution using accumulated prompt attribution data.
   133→	// This uses user edits captured at each prompt start (before agent works),
   134→	// plus any user edits after the final checkpoint (shadow → head).
   135→	logCtx := logging.WithComponent(context.Background(), "attribution")
   136→	var attribution *cpkg.InitialAttribution
   137→	headRef, headErr := repo.Head()
   138→	if headErr != nil {
   139→		logging.Debug(logCtx, "attribution skipped: failed to get HEAD",
   140→			slog.String("error", headErr.Error()))
   141→	} else {
   142→		headCommit, commitErr := repo.CommitObject(headRef.Hash())
   143→		if commitErr != nil {
   144→			logging.Debug(logCtx, "attribution skipped: failed to get HEAD commit",
   145→				slog.String("error", commitErr.Error()))
   146→		} else {
   147→			headTree, treeErr := headCommit.Tree()
   148→			if treeErr != nil {
   149→				logging.Debug(logCtx, "attribution skipped: failed to get HEAD tree",
   150→					slog.String("error", treeErr.Error()))
   151→			} else {
   152→				// Get shadow branch tree (checkpoint tree - what the agent wrote)
   153→				shadowCommit, shadowErr := repo.CommitObject(ref.Hash())
   154→				if shadowErr != nil {
   155→					logging.Debug(logCtx, "attribution skipped: failed to get shadow commit",
   156→						slog.String("error", shadowErr.Error()),
   157→						slog.String("shadow_ref", ref.Hash().String()))
   158→				} else {
   159→					shadowTree, shadowTreeErr := shadowCommit.Tree()
   160→					if shadowTreeErr != nil {
   161→						logging.Debug(logCtx, "attribution skipped: failed to get shadow tree",
   162→							slog.String("error", shadowTreeErr.Error()))
   163→					} else {
   164→						// Get base tree (state before session started)
   165→						var baseTree *object.Tree
   166→						if baseCommit, baseErr := repo.CommitObject(plumbing.NewHash(state.BaseCommit)); baseErr == nil {
   167→							if tree, baseTErr := baseCommit.Tree(); baseTErr == nil {
   168→								baseTree = tree
   169→							} else {
   170→								logging.Debug(logCtx, "attribution: base tree unavailable",
   171→									slog.String("error", baseTErr.Error()))
   172→							}
   173→						} else {
   174→							logging.Debug(logCtx, "attribution: base commit unavailable",
   175→								slog.String("error", baseErr.Error()),
   176→								slog.String("base_commit", state.BaseCommit))
   177→						}
   178→
   179→						// Log accumulated prompt attributions for debugging
   180→						var totalUserAdded, totalUserRemoved int
   181→						for i, pa := range state.PromptAttributions {
   182→							totalUserAdded += pa.UserLinesAdded
   183→							totalUserRemoved += pa.UserLinesRemoved
   184→							logging.Debug(logCtx, "prompt attribution data",
   185→								slog.Int("checkpoint", pa.CheckpointNumber),
   186→								slog.Int("user_added", pa.UserLinesAdded),
   187→								slog.Int("user_removed", pa.UserLinesRemoved),
   188→								slog.Int("agent_added", pa.AgentLinesAdded),
   189→								slog.Int("agent_removed", pa.AgentLinesRemoved),
   190→								slog.Int("index", i))
   191→						}
   192→
   193→						attribution = CalculateAttributionWithAccumulated(
   194→							baseTree,
   195→							shadowTree,
   196→							headTree,
   197→							sessionData.FilesTouched,
   198→							state.PromptAttributions,
   199→						)
   200→
   201→						if attribution != nil {
   202→							logging.Info(logCtx, "attribution calculated",
   203→								slog.Int("agent_lines", attribution.AgentLines),
   204→								slog.Int("human_added", attribution.HumanAdded),
   205→								slog.Int("human_modified", attribution.HumanModified),
   206→								slog.Int("human_removed", attribution.HumanRemoved),
   207→								slog.Int("total_committed", attribution.TotalCommitted),
   208→								slog.Float64("agent_percentage", attribution.AgentPercentage),
   209→								slog.Int("accumulated_user_added", totalUserAdded),
   210→								slog.Int("accumulated_user_removed", totalUserRemoved),
   211→								slog.Int("files_touched", len(sessionData.FilesTouched)))
   212→						}
   213→					}
   214→				}
   215→			}
   216→		}
   217→	}
   218→
   219→	// Write checkpoint metadata using the checkpoint store
   220→	if err := store.WriteCommitted(context.Background(), cpkg.WriteCommittedOptions{
   221→		CheckpointID:                checkpointID,
   222→		SessionID:                   state.SessionID,
   223→		Strategy:                    StrategyNameManualCommit,
   224→		Branch:                      branchName,
   225→		Transcript:                  sessionData.Transcript,
   226→		Prompts:                     sessionData.Prompts,
   227→		Context:                     sessionData.Context,
   228→		FilesTouched:                sessionData.FilesTouched,
   229→		CheckpointsCount:            state.CheckpointCount,
   230→		EphemeralBranch:             shadowBranchName,
   231→		AuthorName:                  authorName,
   232→		AuthorEmail:                 authorEmail,
   233→		Agent:                       state.AgentType,
   234→		TranscriptIdentifierAtStart: state.TranscriptIdentifierAtStart,
   235→		TranscriptLinesAtStart:      state.TranscriptLinesAtStart,
   236→		TokenUsage:                  sessionData.TokenUsage,
   237→		InitialAttribution:          attribution,
   238→	}); err != nil {
   239→		return nil, fmt.Errorf("failed to write checkpoint metadata: %w", err)
   240→	}
   241→
   242→	return &CondenseResult{
   243→		CheckpointID:         checkpointID,
   244→		SessionID:            state.SessionID,
   245→		CheckpointsCount:     state.CheckpointCount,
   246→		FilesTouched:         sessionData.FilesTouched,
   247→		TotalTranscriptLines: sessionData.FullTranscriptLines,
   248→	}, nil
   249→}
   250→
   251→// extractSessionData extracts session data from the shadow branch.
   252→// filesTouched is the list of files tracked during the session (from SessionState.FilesTouched).
   253→// agentType identifies the agent (e.g., "Gemini CLI", "Claude Code") to determine transcript format.
   254→func (s *ManualCommitStrategy) extractSessionData(repo *git.Repository, shadowRef plumbing.Hash, sessionID string, filesTouched []string, agentType agent.AgentType) (*ExtractedSessionData, error) {
   255→	commit, err := repo.CommitObject(shadowRef)
   256→	if err != nil {
   257→		return nil, fmt.Errorf("failed to get commit object: %w", err)
   258→	}
   259→
   260→	tree, err := commit.Tree()
   261→	if err != nil {
   262→		return nil, fmt.Errorf("failed to get commit tree: %w", err)
   263→	}
   264→
   265→	data := &ExtractedSessionData{}
   266→	// sessionID is already an "entire session ID" (with date prefix)
   267→	metadataDir := paths.SessionMetadataDirFromEntireID(sessionID)
   268→
   269→	// Extract transcript
   270→	var fullTranscript string
   271→	if file, fileErr := tree.File(metadataDir + "/" + paths.TranscriptFileName); fileErr == nil {
   272→		if content, contentErr := file.Contents(); contentErr == nil {
   273→			fullTranscript = content
   274→		}
   275→	} else if file, fileErr := tree.File(metadataDir + "/" + paths.TranscriptFileNameLegacy); fileErr == nil {
   276→		if content, contentErr := file.Contents(); contentErr == nil {
   277→			fullTranscript = content
   278→		}
   279→	}
   280→
   281→	// Process transcript based on agent type
   282→	if fullTranscript != "" {
   283→		// Check if this is a Gemini CLI transcript (JSON format, not JSONL)
   284→		isGeminiFormat := agentType == agent.AgentTypeGemini || isGeminiJSONTranscript(fullTranscript)
   285→
   286→		if isGeminiFormat {
   287→			// Gemini uses JSON format with a "messages" array
   288→			data.Transcript = []byte(fullTranscript)
   289→			data.FullTranscriptLines = 1 // JSON is a single "line"
   290→			data.Prompts = extractUserPromptsFromGeminiJSON(fullTranscript)
   291→			data.Context = generateContextFromPrompts(data.Prompts)
   292→		} else {
   293→			// Claude Code and others use JSONL format (one JSON object per line)
   294→			allLines := strings.Split(fullTranscript, "\n")
   295→
   296→			// Trim trailing empty lines (from final \n in JSONL)
   297→			for len(allLines) > 0 && strings.TrimSpace(allLines[len(allLines)-1]) == "" {
   298→				allLines = allLines[:len(allLines)-1]
   299→			}
   300→
   301→			data.FullTranscriptLines = len(allLines)
   302→
   303→			// Always store the full transcript for complete session history
   304→			data.Transcript = []byte(strings.Join(allLines, "\n"))
   305→
   306→			// Extract prompts from the full transcript
   307→			data.Prompts = extractUserPromptsFromLines(allLines)
   308→
   309→			// Generate context from prompts
   310→			data.Context = generateContextFromPrompts(data.Prompts)
   311→		}
   312→	}
   313→
   314→	// Use tracked files from session state (not all files in tree)
   315→	data.FilesTouched = filesTouched
   316→
   317→	// Calculate token usage from the extracted transcript portion
   318→	if len(data.Transcript) > 0 {
   319→		transcriptLines, err := claudecode.ParseTranscript(data.Transcript)
   320→		if err == nil && len(transcriptLines) > 0 {
   321→			data.TokenUsage = claudecode.CalculateTokenUsage(transcriptLines)
   322→		}
   323→	}
   324→
   325→	return data, nil
   326→}
   327→
   328→// isGeminiJSONTranscript detects if the transcript is in Gemini's JSON format.
   329→// Gemini transcripts start with a JSON object containing a "messages" array.
   330→func isGeminiJSONTranscript(content string) bool {
   331→	content = strings.TrimSpace(content)
   332→	// Quick check: Gemini JSON starts with { and contains "messages"
   333→	if !strings.HasPrefix(content, "{") {
   334→		return false
   335→	}
   336→	// Try to parse as Gemini format
   337→	var transcript struct {
   338→		Messages []json.RawMessage `json:"messages"`
   339→	}
   340→	if err := json.Unmarshal([]byte(content), &transcript); err != nil {
   341→		return false
   342→	}
   343→	return len(transcript.Messages) > 0
   344→}
   345→
   346→// extractUserPromptsFromGeminiJSON extracts user prompts from Gemini's JSON transcript format.
   347→// Gemini transcripts are structured as: {"messages": [{"type": "user", "content": "..."}, ...]}
   348→func extractUserPromptsFromGeminiJSON(content string) []string {
   349→	var transcript struct {
   350→		Messages []struct {
   351→			Type    string `json:"type"`
   352→			Content string `json:"content"`
   353→		} `json:"messages"`
   354→	}
   355→
   356→	if err := json.Unmarshal([]byte(content), &transcript); err != nil {
   357→		return nil
   358→	}
   359→
   360→	var prompts []string
   361→	for _, msg := range transcript.Messages {
   362→		if msg.Type == "user" && msg.Content != "" {
   363→			// Strip IDE context tags for consistency with Claude Code handling
   364→			cleaned := textutil.StripIDEContextTags(msg.Content)
   365→			if cleaned != "" {
   366→				prompts = append(prompts, cleaned)
   367→			}
   368→		}
   369→	}
   370→
   371→	return prompts
   372→}
   373→
   374→// extractUserPromptsFromLines extracts user prompts from JSONL transcript lines.
   375→// IDE-injected context tags (like <ide_opened_file>) are stripped from the results.
   376→func extractUserPromptsFromLines(lines []string) []string {
   377→	var prompts []string
   378→	for _, line := range lines {
   379→		line = strings.TrimSpace(line)
   380→		if line == "" {
   381→			continue
   382→		}
   383→
   384→		var entry map[string]interface{}
   385→		if err := json.Unmarshal([]byte(line), &entry); err != nil {
   386→			continue
   387→		}
   388→
   389→		// Check for user message (supports both "human" and "user" types)
   390→		msgType, ok := entry["type"].(string)
   391→		if !ok || (msgType != "human" && msgType != "user") {
   392→			continue
   393→		}
   394→
   395→		// Extract message content
   396→		message, ok := entry["message"].(map[string]interface{})
   397→		if !ok {
   398→			continue
   399→		}
   400→
   401→		// Handle string content
   402→		if content, ok := message["content"].(string); ok && content != "" {
   403→			cleaned := textutil.StripIDEContextTags(content)
   404→			if cleaned != "" {
   405→				prompts = append(prompts, cleaned)
   406→			}
   407→			continue
   408→		}
   409→
   410→		// Handle array content (e.g., multiple text blocks from VSCode)
   411→		if arr, ok := message["content"].([]interface{}); ok {
   412→			var texts []string
   413→			for _, item := range arr {
   414→				if m, ok := item.(map[string]interface{}); ok {
   415→					if m["type"] == "text" {
   416→						if text, ok := m["text"].(string); ok {
   417→							texts = append(texts, text)
   418→						}
   419→					}
   420→				}
   421→			}
   422→			if len(texts) > 0 {
   423→				cleaned := textutil.StripIDEContextTags(strings.Join(texts, "\n\n"))
   424→				if cleaned != "" {
   425→					prompts = append(prompts, cleaned)
   426→				}
   427→			}
   428→		}
   429→	}
   430→	return prompts
   431→}
   432→
   433→// generateContextFromPrompts generates context.md content from a list of prompts.
   434→func generateContextFromPrompts(prompts []string) []byte {
   435→	if len(prompts) == 0 {
   436→		return nil
   437→	}
   438→
   439→	var buf strings.Builder
   440→	buf.WriteString("# Session Context\n\n")
   441→	buf.WriteString("## User Prompts\n\n")
   442→
   443→	for i, prompt := range prompts {
   444→		// Truncate very long prompts for readability
   445→		displayPrompt := prompt
   446→		if len(displayPrompt) > 500 {
   447→			displayPrompt = displayPrompt[:500] + "..."
   448→		}
   449→		buf.WriteString(fmt.Sprintf("### Prompt %d\n\n", i+1))
   450→		buf.WriteString(displayPrompt)
   451→		buf.WriteString("\n\n")
   452→	}
   453→
   454→	return []byte(buf.String())
   455→}
